using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------

var notes = new ResearchNotes();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            Console.ResetColor();

            // Simulated search results – swap with a real API (Bing, Google, etc.)
            var results = query.ToLowerInvariant() switch
            {
                var q when q.Contains("quantum computing") =>
                    """
                    1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
                    2. Google's Willow chip (2024) demonstrated quantum error correction below threshold for the first time.
                    3. IBM plans to deliver a 100,000-qubit system by 2033.
                    4. Key algorithms: Shor's (factoring), Grover's (search), VQE (chemistry simulation).
                    5. Current challenges: decoherence, error rates, extreme cooling requirements (~15 millikelvin).
                    """,
                var q when q.Contains("application") || q.Contains("use case") =>
                    """
                    1. Drug discovery: simulating molecular interactions far faster than classical computers.
                    2. Cryptography: quantum computers threaten RSA/ECC; post-quantum cryptography is being standardized (NIST 2024).
                    3. Optimization: supply chain, financial portfolio, and traffic routing problems.
                    4. Machine learning: quantum kernels and variational circuits show promise for certain data patterns.
                    5. Climate modeling: more accurate simulations of atmospheric and oceanic systems.
                    """,
                var q when q.Contains("recent") || q.Contains("2024") || q.Contains("2025") || q.Contains("breakthrough") =>
                    """
                    1. Microsoft announced Majorana 1, the first topological qubit chip, in February 2025.
                    2. Google's Willow chip achieved a benchmark in under 5 minutes that would take classical supercomputers 10 septillion years.
                    3. NIST finalized the first three post-quantum cryptography standards (ML-KEM, ML-DSA, SLH-DSA) in August 2024.
                    4. Quantinuum demonstrated the first fault-tolerant quantum circuit below physical error rates.
                    5. China's Jiuzhang 3.0 photonic quantum computer achieved quantum advantage on Gaussian boson sampling.
                    """,
                _ =>
                    $"""
                    1. "{query}" is a broad topic with ongoing research.
                    2. Multiple academic papers and industry reports cover this area.
                    3. Key institutions include MIT, Google Quantum AI, IBM Research, and Microsoft Research.
                    4. For the latest developments, check arxiv.org and major tech blogs.
                    """
            };

            return results;
        },
        new AIFunctionFactoryOptions { Name = "web_search", Description = "Search the web for information on a given query" }),

    AIFunctionFactory.Create(
        ([Description("Title or label for this note")] string title,
         [Description("Content of the note to save")] string content) =>
        {
            notes.Add(title, content);
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            Console.ResetColor();
            return $"Note '{title}' saved successfully.";
        },
        new AIFunctionFactoryOptions { Name = "save_note", Description = "Save a research note with a title and content for later reference" }),

    AIFunctionFactory.Create(
        () =>
        {
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine("  📋 Reading all notes...");
            Console.ResetColor();
            return notes.GetAll();
        },
        new AIFunctionFactoryOptions { Name = "get_notes", Description = "Retrieve all previously saved research notes" }),
};

// ---------------------------------------------------------------------------
// Build the agent
// ---------------------------------------------------------------------------

string endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT")
                  ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                  ?? "https://api.openai.com/v1";

string apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set OPENAI_API_KEY (or AZURE_OPENAI_API_KEY) to run the research agent.");

string model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

const string instructions = """
    You are a research agent. When the user gives you a topic:
    1. Use the web_search tool multiple times to gather information from different angles.
    2. Use the save_note tool to record key findings as you go.
    3. After gathering enough information, use get_notes to review everything you've collected.
    4. Produce a well-structured summary with sections, key facts, and a conclusion.
    Be thorough — perform at least 3 searches before summarizing.
    """;

var agent = new ChatClientAgent(chatClient, instructions, name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking", tools: tools);

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔬 AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : "quantum computing breakthroughs and applications";

Console.WriteLine($"📌 Research topic: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

AgentResponse response = await agent.RunAsync(messages);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("📄 RESEARCH SUMMARY");
Console.ResetColor();
Console.WriteLine(new string('═', 50));
Console.WriteLine();
Console.WriteLine(response.Text);

// ---------------------------------------------------------------------------
// Helper class for notes
// ---------------------------------------------------------------------------

class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}\n{_notes[i].Content}\n");

        return sb.ToString();
    }
}

